mapper.select:
select a.works_id, a.competition_series_id, (select competition_name from competition_main_info where
competition_id = (select competition_id from competition_series_info where competition_series_id = a.competition_series_id)) competition_name,
a.stage_id, a.works_name, a.works_url, a.works_score,a.is_advance,a.certificate_url,a.user_id, a.team_code, a.works_rank, a.works_desc,
a.works_status,a.competition_track_name, a.group_classify,a.create_by, a.create_time, a.update_by, a.update_time, a.version, a.del_flag, a.org_id
from competition_works a
where a.del_flag = '0'
     and a.competition_series_id = #{competitionSeriesId}

        and a.stage_id = #{stageId}

     and a.works_name like concat('%', #{worksName}, '%')
     and a.works_url = #{worksUrl}
     and a.works_score = #{worksScore}
     and a.user_id = #{userId}
     and a.team_code = #{teamCode}
     and a.works_rank = #{worksRank}
     and a.is_advance = #{isAdvance}

        and a.competition_track_name = #{competitionTrackName}


        and a.group_classify = #{groupClassify}

     and a.org_id = #{orgId}

        and a.works_score is null


        and a.works_score is not null


        AND works_id IN

            #{item}



    ${params.dataScope}
    order by a.works_score desc


where works_score is not null and del_flag = '0' and is_advance is null

    and competition_series_id = #{competitionSeriesId}


    and stage_id = #{stageId}

order by works_score desc

select sum(works_score) 'worksScore',user_id 'userId',org_id 'orgId' from competition_works
where competition_series_id = #{competitionSeriesId}
group by user_id order by works_score desc


where user_id = #{userId}
and stage_id = #{stageId}
and competition_series_id = #{competitionSeriesId}

mapper.update:
update competition_works
competition_series_id = #{competitionSeriesId}, stage_id = #{stageId}, works_name = #{worksName}, works_url = #{worksUrl}, works_score = #{worksScore}, user_id = #{userId}, team_code = #{teamCode}, works_rank = #{worksRank}, works_desc = #{worksDesc}, works_status = #{worksStatus}, is_advance = #{isAdvance}, certificate_url = #{certificateUrl}, competition_track_name = #{competitionTrackName}, group_classify = #{groupClassify}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime}, version = version+1, del_flag = #{delFlag}, org_id = #{orgId},
where works_id = #{worksId}

update competition_works
works_score = CASE
WHEN works_id = #{item.worksId} THEN #{item.worksScore}
ELSE works_score END,
is_advance = CASE
WHEN works_id = #{item.worksId} THEN #{item.isAdvance}
ELSE is_advance END,
works_rank = CASE
WHEN works_id = #{item.worksId} THEN #{item.worksRank}
ELSE works_rank END,
update_time = NOW(), version = version + 1
WHERE works_id IN
#{item.worksId}
